Output21Using Bottom-Up DP (Tabulation) - O(n*x*m) Time and O(n*x) SpaceThe idea is to fill the DP table based on previous values. For each dice i and sum j, we try all the values k from 1 to m. The table is filled in an iterative manner from i = 1 to i = n and for each sum j from 1 to x. The dynamic programming relation is as follows: dp[i][j] = sum(dp[i-1][j-k]) where k is in range [1, m] and j-k >= 0.
            C++

    // C++ program to implement
// dice throw problem using tabulation
#include <bits/stdc++.h>
using namespace std;

int noOfWays(int m, int n, int x) {

    // Create a 2D dp array with (n+1) rows and (x+1) columns
    // dp[i][j] will store the number of ways to get a sum 
  	// of 'j' using 'i' dice
    vector<vector<int>> dp(n + 1, vector<int>(x + 1, 0));

    // Base case: There is 1 way to get
  	// a sum of 0 with 0 dice
    dp[0][0] = 1;

    // Loop through each dice (i) from 1 to n
    for (int i = 1; i <= n; i++) {

        // Loop through each sum (j) from 1 to x
        for (int j = 1; j <= x; j++) {

            // Loop through all possible dice values (k) from 1 to m
            // and if the sum j - k is valid (non-negative), 
          	// add the number of ways from dp[i-1][j-k]
            for (int k = 1; k <= m && j - k >= 0; k++) {
                dp[i][j] += dp[i - 1][j - k];
            }
        }
    }

    // The result will be in dp[n][x], which contains
  	// the number of ways to get sum 'x' using 'n' dice
    return dp[n][x];
}

int main() {
    int m = 6, n = 3, x = 8;
    cout << noOfWays(m, n, x);
}


